<?php
declare(strict_types=1);namespace App\Controller;use App\Exception\AuthException;use App\Http\AgentAdminResponseFactory;use App\Service\BillingService;use App\View\BillingPageRenderer;use Psr\Http\Message\ResponseInterface;
/** 处理后台付款确认、佣金配置和供应商结算确认。 */
final class BillingAdminController extends AbstractController{public function __construct(private BillingService$billing,private BillingPageRenderer$pages,private AgentAdminResponseFactory$responses){}public function index():ResponseInterface{return$this->responses->html($this->pages->adminConfirmations($this->billing->pendingProofs(),$this->csrf($this->session())));}public function confirmPayment():ResponseInterface{return$this->write(fn(int$a)=>$this->billing->confirmPayment($a,$this->id('proof_id')));}public function commission():ResponseInterface{return$this->write(fn(int$a)=>$this->billing->setCommission($a,$this->id('supplier_profile_id'),$this->id('commission_bps',true)));}public function settlement():ResponseInterface{return$this->write(fn(int$a)=>$this->billing->confirmSettlement($a,$this->id('settlement_id')));}private function write(callable$f):ResponseInterface{$s=$this->session();$v=$this->request->input('_csrf','');if(!is_string($v)||$this->csrf($s)===''||!hash_equals($this->csrf($s),$v))return$this->responses->html($this->pages->adminConfirmations([],$this->csrf($s)),419);try{$f((int)$s['admin_id']);return$this->responses->redirect('/agent_admin/billing',303);}catch(AuthException$e){return$this->responses->html($this->pages->adminConfirmations([],$this->csrf($s)),$e->status());}}private function session():array{$s=$this->request->getAttribute('admin_session');return is_array($s)?$s:[];}private function csrf(array$s):string{$v=$s['csrf_token']??'';return is_string($v)?$v:'';}private function id(string$k,bool$zero=false):int{$v=$this->request->input($k);if((is_int($v)&&($v>0||$zero&&$v===0))||(is_string($v)&&preg_match($zero?'/^[0-9]+$/D':'/^[1-9][0-9]*$/D',$v)))return(int)$v;throw AuthException::badRequest('标识无效。');}}
